1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { AudioManager } from '../systems/AudioManager';
4	
5	/**
6	 * BootScene — the first, minimal scene. Applies the persisted mute preference to
7	 * the sound manager, installs the long-lived audio-unlock gesture listener, and
8	 * hands straight off to PreloadScene. (Scale/physics are configured once in
9	 * main.ts; nothing to load for the boot screen itself.)
10	 */
11	export class BootScene extends Phaser.Scene {
12	  constructor() {
13	    super({ key: SceneKey.Boot });
14	  }
15	
16	  create(): void {
17	    AudioManager.apply(this.sound);
18	    // Attach the first-gesture audio unlock on `window` (not scene.input) so it
19	    // survives the immediate hand-off to Preload/Menu and fires on the REAL tap.
20	    AudioManager.installAudioUnlock(this.sound);
21	    this.scene.start(SceneKey.Preload);
22	  }
23	}
