1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { createButton } from '../ui/Button';
7	import { AudioManager } from '../systems/AudioManager';
8	
9	/**
10	 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
11	 * analytics (start_game fires when the run actually begins, in GameScene).
12	 */
13	export class MenuScene extends Phaser.Scene {
14	  constructor() {
15	    super({ key: SceneKey.Menu });
16	  }
17	
18	  create(): void {
19	    const cx = GAME_WIDTH / 2;
20	
21	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
22	    // The title/logo is the `ui_title_logo` asset. (The `menu_title` string is
23	    // reserved for the document/share title; we don't draw it over the logo.)
24	    this.add.image(cx, 180, KEYS.ui_title_logo);
25	
26	    this.add
27	      .text(cx, 330, t('menu_subtitle'), {
28	        fontFamily: 'system-ui, sans-serif',
29	        fontSize: '24px',
30	        color: '#3a444d',
31	      })
32	      .setOrigin(0.5);
33	
34	    createButton(this, {
35	      x: cx,
36	      y: 450,
37	      texture: KEYS.ui_btn_play,
38	      label: t('menu_play'),
39	      onClick: () => this.scene.start(SceneKey.Game),
40	    });
41	
42	    this.add
43	      .text(cx, 550, t('menu_hint'), {
44	        fontFamily: 'system-ui, sans-serif',
45	        fontSize: '20px',
46	        color: '#3a444d',
47	      })
48	      .setOrigin(0.5);
49	
50	    this.buildMuteToggle();
51	  }
52	
53	  private buildMuteToggle(): void {
54	    const muteBtn = this.add
55	      .image(GAME_WIDTH - 52, 52, this.muteTexture())
56	      .setInteractive({ useHandCursor: true });
57	
58	    const label = this.add
59	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
60	        fontFamily: 'system-ui, sans-serif',
61	        fontSize: '14px',
62	        color: '#9fb0bd',
63	      })
64	      .setOrigin(0.5, 0);
65	
66	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
67	      AudioManager.toggle(this.sound);
68	      muteBtn.setTexture(this.muteTexture());
69	      label.setText(this.muteLabel());
70	    });
71	  }
72	
73	  private muteTexture(): string {
74	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
75	  }
76	
77	  private muteLabel(): string {
78	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
79	  }
80	}
