1	// gen-placeholders.mts — emit a greybox placeholder SVG for EVERY asset key.
2	//
3	// Run: `npm run gen:placeholders` (executes via `tsx`, which resolves the TS
4	// import below). Each file is a single colored <rect> at the key's logical
5	// dimensions with the key name + dimensions as visible text, so the app runs
6	// end-to-end in Phase 1. Phase 2 REPLACES these files against the EXACT same
7	// keys/paths/dimensions.
8	//
9	// SINGLE SOURCE OF TRUTH: this reads `src/config/assetManifest.ts` directly, so
10	// a new manifest key can never drift out of lock-step with the generated art —
11	// add a key there and its greybox is emitted here automatically.
12	
13	import { mkdirSync, writeFileSync } from 'node:fs';
14	import { dirname, join } from 'node:path';
15	import { fileURLToPath } from 'node:url';
16	import { ASSET_MANIFEST } from '../src/config/assetManifest';
17	
18	const OUT_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'assets');
19	
20	/** Fill colour per namespace folder (purely to make greyboxes scannable). */
21	const COLORS: Record<string, string> = {
22	  dog: '#cfd8e3',
23	  env: '#d6e8cf',
24	  entities: '#f2d7a8',
25	  vfx: '#e6d3f2',
26	  ui: '#dfe3e8',
27	  screens: '#eef1f4',
28	};
29	const FALLBACK_COLOR = '#dfe3e8';
30	
31	/** Font size that fits `text` inside `w` (approx 0.6em advance for monospace). */
32	function fitFont(text: string, w: number, h: number, cap: number): number {
33	  const byHeight = Math.floor(Math.min(w, h) / 5);
34	  const byWidth = Math.floor((w - 8) / (text.length * 0.62));
35	  return Math.max(8, Math.min(byHeight, byWidth, cap));
36	}
37	
38	function svg(key: string, w: number, h: number, color: string): string {
39	  const dims = `${w}x${h}`;
40	  const keyFs = fitFont(key, w, h, 26);
41	  const dimFs = fitFont(dims, w, h, Math.max(8, Math.round(keyFs * 0.72)));
42	  const cx = w / 2;
43	  const cy = h / 2;
44	  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
45	  <rect x="1" y="1" width="${w - 2}" height="${h - 2}" rx="6" fill="${color}" stroke="#5b6670" stroke-width="2"/>
46	  <text x="${cx}" y="${cy - keyFs * 0.15}" font-family="monospace" font-size="${keyFs}" fill="#20272e" text-anchor="middle" dominant-baseline="middle">${key}</text>
47	  <text x="${cx}" y="${cy + keyFs}" font-family="monospace" font-size="${dimFs}" fill="#48525c" text-anchor="middle" dominant-baseline="middle">${dims}</text>
48	</svg>
49	`;
50	}
51	
52	let count = 0;
53	for (const a of ASSET_MANIFEST) {
54	  // `path` is `assets/<folder>/<key>.svg` — derive the folder from it.
55	  const folder = a.path.split('/')[1] ?? '';
56	  const color = COLORS[folder] ?? FALLBACK_COLOR;
57	  const dir = join(OUT_ROOT, folder);
58	  mkdirSync(dir, { recursive: true });
59	  writeFileSync(join(dir, `${a.key}.svg`), svg(a.key, a.width, a.height, color));
60	  count += 1;
61	}
62	
63	console.log(`Generated ${count} placeholder SVGs under public/assets/ (source: src/config/assetManifest.ts)`);
