26	    position: 'fixed',
27	    top: '0',
28	    left: '0',
29	    width: '100%',
30	    height: '100%',
31	    display: 'none',
32	    alignItems: 'center',
33	    justifyContent: 'center',
34	    background: 'rgba(15, 20, 24, 0.92)',
35	    color: '#f4f7fa',
36	    zIndex: '9999',
