1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { ASSET_MANIFEST } from '../config/assetManifest';
4	import { t } from '../i18n/strings';
5	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
6	
7	/**
8	 * PreloadScene — loads EVERY asset from the shared manifest (as SVGs at their
9	 * logical sizes) behind a loading bar, then advances to the menu. Nothing
10	 * critical is lazy-loaded (spec §10.5). (Audio unlock is installed once in
11	 * BootScene on a long-lived window listener, not here.)
12	 */
13	export class PreloadScene extends Phaser.Scene {
14	  constructor() {
15	    super({ key: SceneKey.Preload });
16	  }
17	
18	  preload(): void {
19	    this.buildLoadingBar();
20	
21	    // Fail LOUD if any manifest key is missing on disk (e.g. a new key added to
22	    // assetManifest.ts without regenerating placeholders → a silent 404). This
23	    // is a real error path, not log spam.
24	    this.load.on(Phaser.Loader.Events.FILE_LOAD_ERROR, (file: Phaser.Loader.File) => {
25	      console.error(`[assets] failed to load "${file.key}" from ${file.src} — is the SVG present?`);
26	    });
27	
28	    // The manifest is the single source of truth: iterate & load each SVG.
29	    for (const a of ASSET_MANIFEST) {
30	      this.load.svg(a.key, a.path, { width: a.width, height: a.height });
31	    }
32	  }
33	
34	  create(): void {
35	    this.scene.start(SceneKey.Menu);
36	  }
37	
38	  private buildLoadingBar(): void {
39	    const cx = GAME_WIDTH / 2;
40	    const cy = GAME_HEIGHT / 2;
41	    const barW = 520;
42	    const barH = 26;
43	
44	    this.add
45	      .text(cx, cy - 48, t('loading'), {
46	        fontFamily: 'system-ui, sans-serif',
47	        fontSize: '22px',
48	        color: '#f4f7fa',
49	      })
50	      .setOrigin(0.5);
51	
52	    const frame = this.add.graphics();
53	    frame.lineStyle(2, 0x5b6670, 1);
54	    frame.strokeRect(cx - barW / 2, cy - barH / 2, barW, barH);
55	
56	    const fill = this.add.graphics();
57	    const pct = this.add
58	      .text(cx, cy + 40, '0%', {
59	        fontFamily: 'system-ui, sans-serif',
60	        fontSize: '16px',
61	        color: '#9fb0bd',
62	      })
63	      .setOrigin(0.5);
64	
65	    this.load.on(Phaser.Loader.Events.PROGRESS, (value: number) => {
66	      fill.clear();
67	      fill.fillStyle(0x6cc04a, 1);
68	      fill.fillRect(cx - barW / 2 + 3, cy - barH / 2 + 3, (barW - 6) * value, barH - 6);
69	      pct.setText(`${Math.round(value * 100)}%`);
70	    });
71	  }
72	}
