18	/**
19	 * GameScene — Phase 1 PLACEHOLDER run screen. It renders the park backdrop, the
20	 * hero, and a HUD, fires `start_game` on entry, and exposes TEMPORARY debug
21	 * controls (on-screen Win/Lose buttons + W/L keys) that end the run, fire
22	 * `finish_game`, and hand a result to ResultsScene. No real gameplay/physics yet
23	 * — this exists purely to make the flow navigable end-to-end.
24	 */
25	export class GameScene extends Phaser.Scene {
26	  private hero!: HeroDog;
27	  private scoreText!: Phaser.GameObjects.Text;
28	  private progressFill!: Phaser.GameObjects.Rectangle;
29	
30	  private elapsedMs = 0;
31	  private score = 0;
32	  private finished = false;
33	
34	  constructor() {
35	    super({ key: SceneKey.Game });
36	  }
37	
38	  create(): void {
39	    this.elapsedMs = 0;
40	    this.score = 0;
41	    this.finished = false;
42	
43	    this.buildBackground();
44	    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
45	    this.buildHud();
46	    // Jump zone BEFORE the debug buttons so the buttons sit on top (topOnly).
47	    this.buildJumpInput();
48	    this.buildDebugFinishControls();
49	
50	    // A round has begun.
51	    track('start_game');
52	
53	    // Keyboard jump (cosmetic hop only; real jump physics is Phase 2).
54	    const space = this.input.keyboard?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);
55	    space?.on('down', () => this.hero.nudgeJump());
56	
57	    // Per-frame accumulator for active-play time (spec §7.2). Wired via the
58	    // scene UPDATE event so a later phase can freeze it during pause cleanly.
59	    this.events.on(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
60	    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
61	      this.events.off(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
62	    });
63	  }
64	
65	  private buildBackground(): void {
66	    const cx = GAME_WIDTH / 2;
67	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.park_bg_far);
68	    this.add.image(cx, GROUND_TOP_Y, KEYS.park_bg_near).setOrigin(0.5, 1);
69	    this.add
70	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
71	      .setOrigin(0.5, 0);
72	    this.add.image(cx, GAME_HEIGHT, KEYS.park_fg_grass).setOrigin(0.5, 1);
73	  }
74	
75	  private buildHud(): void {
76	    // Level-progress bar: the FRAME is the `ui_progress_bar` asset (1180×14) and
77	    // the dynamic fill is a rectangle scaled over its inner track. Phase 2 swaps
78	    // the SVG art against the same key/size; the fill logic is untouched.
79	    const barY = 16;
80	    const barW = 1180; // == ui_progress_bar asset width (see assetManifest)
81	    const barLeft = GAME_WIDTH / 2 - barW / 2;
82	    this.progressFill = this.add
83	      .rectangle(barLeft + 2, barY, barW - 4, 8, 0x6cc04a)
84	      .setOrigin(0, 0.5);
85	    this.progressFill.scaleX = 0;
86	    this.add.image(GAME_WIDTH / 2, barY, KEYS.ui_progress_bar); // frame over the fill
87	
88	    // Score row (top-left): the `ui_score_icon` asset next to the live score.
89	    const rowY = 58;
90	    this.add.image(38, rowY, KEYS.ui_score_icon);
91	    this.scoreText = this.add
92	      .text(68, rowY, `${t('hud_score')}: 0`, {
93	        fontFamily: 'system-ui, sans-serif',
94	        fontSize: '26px',
95	        fontStyle: 'bold',
96	        color: '#20272e',
97	      })
98	      .setOrigin(0, 0.5);
99	
100	    // Hearts (below the score row) — Phase 1 shows all full.
101	    for (let i = 0; i < MAX_HP; i++) {
102	      this.add.image(42 + i * 44, 100, KEYS.ui_heart_full);
103	    }
104	  }
105	
106	  /**
107	   * Jump input. Bound to a full-screen interactive Zone created BEFORE the debug
108	   * buttons, so with `input.topOnly` (Phaser default) a tap on a Win/Lose button
109	   * hits the button only — never also the jump. Real jump physics is Phase 2.
110	   */
111	  private buildJumpInput(): void {
112	    const jumpZone = this.add
113	      .zone(0, 0, GAME_WIDTH, GAME_HEIGHT)
114	      .setOrigin(0, 0)
115	      .setInteractive();
116	    jumpZone.on(Phaser.Input.Events.POINTER_DOWN, () => this.hero.nudgeJump());
117	  }
118	
119	  private buildDebugFinishControls(): void {
120	    this.add
121	      .text(GAME_WIDTH / 2, GAME_HEIGHT - 98, t('game_debug_hint'), {
122	        fontFamily: 'system-ui, sans-serif',
123	        fontSize: '16px',
124	        color: '#20272e',
125	      })
126	      .setOrigin(0.5);
127	
128	    createButton(this, {
129	      x: GAME_WIDTH / 2 - 135,
130	      y: GAME_HEIGHT - 50,
131	      width: 240,
132	      height: 56,
133	      label: t('game_debug_win'),
134	      onClick: () => this.finishRun('win'),
135	    });
136	    createButton(this, {
137	      x: GAME_WIDTH / 2 + 135,
138	      y: GAME_HEIGHT - 50,
139	      width: 240,
140	      height: 56,
141	      label: t('game_debug_lose'),
142	      onClick: () => this.finishRun('lose'),
143	    });
144	
145	    const kb = this.input.keyboard;
146	    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.W).on('down', () => this.finishRun('win'));
147	    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.L).on('down', () => this.finishRun('lose'));
148	  }
149	
150	  private onUpdate(_time: number, delta: number): void {
151	    if (this.finished) return;
152	
153	    this.elapsedMs += delta;
154	    const seconds = this.elapsedMs / 1000;
155	
156	    this.score = Math.floor(seconds * SCORE_SURVIVAL_PER_S);
157	    this.scoreText.setText(`${t('hud_score')}: ${this.score}`);
158	
159	    const progress = Phaser.Math.Clamp(seconds / TARGET_DURATION_S.nominal, 0, 1);
160	    this.progressFill.scaleX = progress;
161	  }
